sys_script.script:
(function executeRule(current, previous) {

    /*
     * Nexora:
     * When an Application is selected,
     * 1. Create Offer Letter
     * 2. Create Student Notification
     */

    var applicationId = current.getUniqueValue();

    // --------------------------------------------------
    // 1. GET STUDENT
    // --------------------------------------------------

    var studentId = current.getValue('student');

    if (!studentId) {
        gs.error('Nexora: No student found on application ' + applicationId);
        return;
    }

    var studentGR = new GlideRecord('x_snc_college_pl_0_student');

    if (!studentGR.get(studentId)) {
        gs.error('Nexora: Student record not found: ' + studentId);
        return;
    }


    // --------------------------------------------------
    // 2. GET PLACEMENT DRIVE
    // --------------------------------------------------

    var driveId = current.getValue('drive');

    if (!driveId) {
        gs.error('Nexora: No placement drive found on application ' + applicationId);
        return;
    }

    var driveGR = new GlideRecord('x_snc_college_pl_0_placement_drive');

    if (!driveGR.get(driveId)) {
        gs.error('Nexora: Placement drive not found: ' + driveId);
        return;
    }


    // --------------------------------------------------
    // 3. GET DISPLAY VALUES
    // --------------------------------------------------

    var companyName = '';

    if (driveGR.isValidField('company')) {
        companyName = driveGR.getDisplayValue('company');
    }

    var driveName = '';

    if (driveGR.isValidField('drive_name')) {
        driveName = driveGR.getDisplayValue('drive_name');
    }

    var jobRole = '';

    if (driveGR.isValidField('job_role')) {
        jobRole = driveGR.getDisplayValue('job_role');
    }


    // --------------------------------------------------
    // 4. CREATE OFFER LETTER
    // --------------------------------------------------

    var offerLetterId = '';

    var existingOffer = new GlideRecord('x_snc_college_pl_0_offer_letter');

    if (existingOffer.isValid()) {

        existingOffer.addQuery('application', applicationId);
        existingOffer.setLimit(1);
        existingOffer.query();

        if (existingOffer.next()) {

            // Offer already exists
            offerLetterId = existingOffer.getUniqueValue();

        } else {

            var offerGR = new GlideRecord(
                'x_snc_college_pl_0_offer_letter'
            );

            offerGR.initialize();

            // Student
            if (offerGR.isValidField('student')) {
                offerGR.setValue('student', studentId);
            }

            // Application
            if (offerGR.isValidField('application')) {
                offerGR.setValue('application', applicationId);
            }

            // Company
            if (offerGR.isValidField('company')) {

                var driveCompanyId = driveGR.getValue('company');

                if (driveCompanyId) {
                    offerGR.setValue('company', driveCompanyId);
                }
            }

            // Offer date
            if (offerGR.isValidField('offer_date')) {
                offerGR.setValue('offer_date', new GlideDateTime());
            }

            offerLetterId = offerGR.insert();

            if (!offerLetterId) {
                gs.error(
                    'Nexora: Unable to create Offer Letter for application ' +
                    applicationId
                );
            }
        }
    }


    // --------------------------------------------------
    // 5. CREATE STUDENT NOTIFICATION
    // --------------------------------------------------

    var notificationGR = new GlideRecord(
        'x_2065256_colleg_0_student_notification'
    );

    notificationGR.initialize();

    // Student
    notificationGR.setValue('student', studentId);

    // Title
    notificationGR.setValue(
        'title',
        'Congratulations! You have been selected'
    );

    // Message
    var message =
        'You have been selected for ' +
        (jobRole || 'the available position') +
        ' at ' +
        (companyName || 'the company') +
        ' through the ' +
        (driveName || 'placement drive') +
        '.';

    notificationGR.setValue('message', message);

    // Type
    notificationGR.setValue('type', 'Selection');

    // Unread
    notificationGR.setValue('is_read', false);

    // Application
    notificationGR.setValue('application', applicationId);

    // Placement Drive
    notificationGR.setValue('placement_drive', driveId);

    // Offer Letter
    if (offerLetterId) {
        notificationGR.setValue('offer_letter', offerLetterId);
    }

    // Link to Offer Letters page
    notificationGR.setValue(
        'action_url',
        '?id=offer-letters'
    );

    var notificationId = notificationGR.insert();

    if (!notificationId) {
        gs.error(
            'Nexora: Unable to create Student Notification for application ' +
            applicationId
        );
    }

})(current, previous);
